 3	public sealed class DiscountRules
 4	{
 5	    public decimal Apply(decimal subtotal, string? code)
 6	    {
 7	        if (subtotal < 0)
 8	        {
 9	            throw new ArgumentOutOfRangeException(nameof(subtotal));
10	        }
11	
12	        if (string.IsNullOrWhiteSpace(code))
13	        {
14	            return subtotal;
15	        }
16	
17	        return code.ToUpperInvariant() switch
18	        {
19	            "SAVE10" => decimal.Round(
20	                subtotal * 0.9m,
21	                2,
22	                MidpointRounding.AwayFromZero),
23	            "FLAT5" => Math.Max(0m, subtotal - 5m),
24	            _ => throw new ArgumentException("Unknown discount code.", nameof(code)),
25	        };
26	    }
27	}

